def get_cache_info(self, options: Values, args: list[str]) -> None:
    if args:
        raise CommandError("Too many arguments")
    num_http_files = len(self._find_http_files(options))
    num_packages = len(self._find_wheels(options, "*"))
    http_cache_location = self._cache_dir(options, "http-v2")
    old_http_cache_location = self._cache_dir(options, "http")
    wheels_cache_location = self._cache_dir(options, "wheels")
    http_cache_size = filesystem.format_size(
        filesystem.directory_size(http_cache_location)
        + filesystem.directory_size(old_http_cache_location)
    )
    wheels_cache_size = filesystem.format_directory_size(wheels_cache_location)
    message = (
        textwrap.dedent(
            """
                Package index page cache location (pip v23.3+): {http_cache_location}
                Package index page cache location (older pips): {old_http_cache_location}
                Package index page cache size: {http_cache_size}
                Number of HTTP files: {num_http_files}
                Locally built wheels location: {wheels_cache_location}
                Locally built wheels size: {wheels_cache_size}
                Number of locally built wheels: {package_count}
            """  # noqa: E501
        )
        .format(
            http_cache_location=http_cache_location,
            old_http_cache_location=old_http_cache_location,
            http_cache_size=http_cache_size,
            num_http_files=num_http_files,
            wheels_cache_location=wheels_cache_location,
            package_count=num_packages,
            wheels_cache_size=wheels_cache_size,
        )
        .strip()
    )
    logger.info(message)

def list_cache_items(self, options: Values, args: list[str]) -> None:
    if len(args) > 1:
        raise CommandError("Too many arguments")
    if args:
        pattern = args[0]
    else:
        pattern = "*"
    files = self._find_wheels(options, pattern)
    if options.list_format == "human":
        self.format_for_human(files)
    else:
        self.format_for_abspath(files)

def format_for_abspath(self, files: list[str]) -> None:
    if files:
        logger.info("\n".join(sorted(files)))

def remove_cache_items(self, options: Values, args: list[str]) -> None:
    if len(args) > 1:
        raise CommandError("Too many arguments")
    if not args:
        raise CommandError("Please provide a pattern")
    files = self._find_wheels(options, args[0])
    no_matching_msg = "No matching packages"
    if args[0] == "*":
        files += self._find_http_files(options)
    else:
        no_matching_msg += f' for pattern "{args[0]}"'
    if not files:
        logger.warning(no_matching_msg)
    bytes_removed = 0
    for filename in files:
        bytes_removed += os.stat(filename).st_size
        os.unlink(filename)
        logger.verbose("Removed %s", filename)
    logger.info("Files removed: %s (%s)", len(files), format_size(bytes_removed))

def purge_cache(self, options: Values, args: list[str]) -> None:
    if args:
        raise CommandError("Too many arguments")
    return self.remove_cache_items(options, ["*"])

def _find_http_files(self, options: Values) -> list[str]:
    old_http_dir = self._cache_dir(options, "http")
    new_http_dir = self._cache_dir(options, "http-v2")
    return filesystem.find_files(old_http_dir, "*") + filesystem.find_files(
        new_http_dir, "*"
    )

def _find_wheels(self, options: Values, pattern: str) -> list[str]:
    wheel_dir = self._cache_dir(options, "wheels")
    pattern = pattern + ("*.whl" if "-" in pattern else "-*.whl")
    return filesystem.find_files(wheel_dir, pattern)

def run(self, options: Values, args: list[str]) -> int:
    package_set, parsing_probs = create_package_set_from_installed()
    missing, conflicting = check_package_set(package_set)
    unsupported = list(
        check_unsupported(
            get_default_environment().iter_installed_distributions(),
            get_supported(),
        )
    )
    for project_name in missing:
        version = package_set[project_name].version
        for dependency in missing[project_name]:
            write_output(
                "%s %s requires %s, which is not installed.",
                project_name,
                version,
                dependency[0],
            )
    for project_name in conflicting:
        version = package_set[project_name].version
        for dep_name, dep_version, req in conflicting[project_name]:
            write_output(
                "%s %s has requirement %s, but you have %s %s.",
                project_name,
                version,
                req,
                dep_name,
                dep_version,
            )
    for package in unsupported:
        write_output(
            "%s %s is not supported on this platform",
            package.raw_name,
            package.version,
        )
    if missing or conflicting or parsing_probs or unsupported:
        return ERROR
    else:
        write_output("No broken requirements found.")
        return SUCCESS

