def _determine_file(self, options: Values, need_value: bool) -> Kind | None:
    file_options = [
        key
        for key, value in (
            (kinds.USER, options.user_file),
            (kinds.GLOBAL, options.global_file),
            (kinds.SITE, options.site_file),
        )
        if value
    ]
    if not file_options:
        if not need_value:
            return None
        elif any(
            os.path.exists(site_config_file)
            for site_config_file in get_configuration_files()[kinds.SITE]
        ):
            return kinds.SITE
        else:
            return kinds.USER
    elif len(file_options) == 1:
        return file_options[0]
    raise PipError(
        "Need exactly one file to operate upon "
        "(--user, --site, --global) to perform."
    )

def list_values(self, options: Values, args: list[str]) -> None:
    self._get_n_args(args, "list", n=0)
    for key, value in sorted(self.configuration.items()):
        for key, value in sorted(value.items()):
            write_output("%s=%r", key, value)

def list_config_values(self, options: Values, args: list[str]) -> None:
    """List config key-value pairs across different config files"""
    self._get_n_args(args, "debug", n=0)
    self.print_env_var_values()
    for variant, files in sorted(self.configuration.iter_config_files()):
        write_output("%s:", variant)
        for fname in files:
            with indent_log():
                file_exists = os.path.exists(fname)
                write_output("%s, exists: %r", fname, file_exists)
                if file_exists:
                    self.print_config_file_values(variant, fname)

def print_config_file_values(self, variant: Kind, fname: str) -> None:
    """Get key-value pairs from the file of a variant"""
    for name, value in self.configuration.get_values_in_config(variant).items():
        with indent_log():
            if name == fname:
                for confname, confvalue in value.items():
                    write_output("%s: %s", confname, confvalue)

def open_in_editor(self, options: Values, args: list[str]) -> None:
    editor = self._determine_editor(options)
    fname = self.configuration.get_file_to_edit()
    if fname is None:
        raise PipError("Could not determine appropriate file.")
    elif '"' in fname:
        raise PipError(
            f'Can not open an editor for a file name containing "\n{fname}'
        )
    try:
        subprocess.check_call(f'{editor} "{fname}"', shell=True)
    except FileNotFoundError as e:
        if not e.filename:
            e.filename = editor
        raise
    except subprocess.CalledProcessError as e:
        raise PipError(f"Editor Subprocess exited with exit code {e.returncode}")

def _get_n_args(self, args: list[str], example: str, n: int) -> Any:
    """Helper to make sure the command got the right number of arguments"""
    if len(args) != n:
        msg = (
            f"Got unexpected number of arguments, expected {n}. "
            f'(example: "{get_prog()} config {example}")'
        )
        raise PipError(msg)
    if n == 1:
        return args[0]
    else:
        return args

