def ETA(self):
    if self.done:
        prefix = 'Done'
        t = self.elapsed
    else:
        prefix = 'ETA '
        if self.max is None:
            t = -1
        elif self.elapsed == 0 or (self.cur == self.min):
            t = 0
        else:
            t = float(self.max - self.min)
            t /= self.cur - self.min
            t = (t - 1) * self.elapsed
    return '%s: %s' % (prefix, self.format_duration(t))
