                          ('tabs',     '»'),
                          ('newlines', '¶')]:
        opt = options.get(name, False)
        if isinstance(opt, str) and len(opt) == 1:
            setattr(self, name, opt)
        else:
            setattr(self, name, (opt and default or ''))
    tabsize = get_int_opt(options, 'tabsize', 8)
    if self.tabs:
        self.tabs += ' ' * (tabsize - 1)
    if self.newlines:
        self.newlines += '\n'
