    if self.wstt:
        spaces = self.spaces or ' '
        tabs = self.tabs or '\t'
        newlines = self.newlines or '\n'
        regex = re.compile(r'\s')

    def replacefunc(wschar):
        if wschar == ' ':
            return spaces
        elif wschar == '\t':
            return tabs
        elif wschar == '\n':
            return newlines
        return wschar
    for ttype, value in stream:
        yield from _replace_special(ttype, value, regex, Whitespace,
                                    replacefunc)
