    spaces, tabs, newlines = self.spaces, self.tabs, self.newlines
    for ttype, value in stream:
        if spaces:
            value = value.replace(' ', spaces)
        if tabs:
            value = value.replace('\t', tabs)
        if newlines:
            value = value.replace('\n', newlines)
        yield ttype, value

