export const AuthProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [user, setUser] = useState<User | null>(null);
  const [loading, setLoading] = useState(true);
  const isLocalDev = isSupabasePlaceholder();

  useEffect(() => {
    if (isLocalDev) {
      // Mock user for local development without Supabase keys
      setUser({
        id: 'local-dev-user-id',
        email: 'dev@preptracker.local',
        user_metadata: { full_name: 'Developer Profile' }
      } as any);
      setLoading(false);
      return;
    }

    // Initialize session and listen to changes
    supabase.auth.getSession().then(({ data: { session } }) => {
      setUser(session?.user ?? null);
      setLoading(false);
    });

    const result = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user ?? null);
      setLoading(false);
    });

    return () => {
      result.data?.subscription?.unsubscribe();
    };
  }, [isLocalDev]);



  // Monkeypatch the global fetch to inject Supabase access token in API headers
  useEffect(() => {
    if (isLocalDev) return;

    const originalFetch = window.fetch;
    window.fetch = async (input, init) => {
      const url = typeof input === 'string' ? input : (input as Request).url;

      // Inject bearer token only for backend API requests
      if (url.startsWith(API_URL)) {
        try {
          const { data: { session } } = await supabase.auth.getSession();
          const token = session?.access_token;
          if (token) {
            init = init || {};
            const headers = new Headers(init.headers || {});
            headers.set('Authorization', `Bearer ${token}`);
            init.headers = headers;
          }
        } catch (err) {
          console.error('[Global Fetch Interceptor] Token retrieval failed:', err);
        }
      }
      return originalFetch(input, init);
    };

    return () => {
      window.fetch = originalFetch; // restore original on unmount
    };
  }, [isLocalDev]);

  const logout = async () => {
    if (isLocalDev) return;
    await supabase.auth.signOut();
  };

  const resetPassword = async (email: string) => {
    if (isLocalDev) return;
    const { error } = await supabase.auth.resetPasswordForEmail(email, {
      redirectTo: `${window.location.origin}/reset-password`,
    });
    if (error) throw error;
  };

  return (
    <AuthContext.Provider value={{ user, loading, isLocalDev, logout, resetPassword }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (context === undefined) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};

interface AuthContextType {
  user: User | null;
  loading: boolean;
  isLocalDev: boolean;
  logout: () => Promise<void>;
  resetPassword: (email: string) => Promise<void>;
}

export const ActivityLogPage: React.FC = () => {
  const queryClient = useQueryClient();
  const [selectedFilterCategory, setSelectedFilterCategory] = useState<string>('ALL');

  // Quick-add form states
  const [date, setDate] = useState<string>(
    new Date(Date.now() - new Date().getTimezoneOffset() * 60000).toISOString().split('T')[0]
  );
  const [category, setCategory] = useState<Category>('DSA');
  const [topic, setTopic] = useState<string>('');
  const [durationMin, setDurationMin] = useState<number>(45);
  const [notes, setNotes] = useState<string>('');

  // Inline editing states
  const [editingId, setEditingId] = useState<number | null>(null);
  const [editDate, setEditDate] = useState<string>('');
  const [editCategory, setEditCategory] = useState<Category>('DSA');
  const [editTopic, setEditTopic] = useState<string>('');
  const [editDurationMin, setEditDurationMin] = useState<number>(0);
  const [editNotes, setEditNotes] = useState<string>('');

  // Fetch activity logs
  const { data: logs, isLoading } = useQuery<ActivityLog[]>({
    queryKey: ['logs', selectedFilterCategory],
    queryFn: async () => {
      const url = new URL(`${API_URL}/logs`);
      if (selectedFilterCategory !== 'ALL') {
        url.searchParams.append('category', selectedFilterCategory);
      }
      const res = await fetch(url.toString());
      if (!res.ok) throw new Error('Failed to fetch activity logs');
      return res.json();
    }
  });

  // Create log mutation
  const createMutation = useMutation({
    mutationFn: async (newLog: Partial<ActivityLog>) => {
      const res = await fetch(`${API_URL}/logs`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(newLog),
      });
      if (!res.ok) throw new Error('Failed to create log');
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['logs'] });
      queryClient.invalidateQueries({ queryKey: ['analyticsSummary'] });
      queryClient.invalidateQueries({ queryKey: ['heatmap'] });
      // Reset input fields (keep date as today)
      setTopic('');
      setNotes('');
    }
  });

  // Update log mutation
  const updateMutation = useMutation({
    mutationFn: async (updatedLog: Partial<ActivityLog> & { id: number }) => {
      const res = await fetch(`${API_URL}/logs/${updatedLog.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updatedLog),
      });
      if (!res.ok) throw new Error('Failed to update log');
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['logs'] });
      queryClient.invalidateQueries({ queryKey: ['analyticsSummary'] });
      queryClient.invalidateQueries({ queryKey: ['heatmap'] });
      setEditingId(null);
