                Log New Application
              </h3>
              <button 
                onClick={() => setIsModalOpen(false)}
                className="text-slate-400 hover:text-slate-200"
              >
                <X className="w-4 h-4" />
              </button>
            </div>

            {/* Form */}
            <form onSubmit={handleSubmit} className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-4">
                <div className="flex flex-col gap-1.5 col-span-2">
                  <label className="font-mono text-[10px] text-slate-400 uppercase tracking-wider">Company Name</label>
                  <input 
                    type="text"
                    placeholder="e.g. Google, Anthropic, Stripe"
                    value={companyName}
                    onChange={(e) => setCompanyName(e.target.value)}
                    className="bg-slate-900 border border-slate-800 rounded px-3 py-2 text-xs text-slate-300 focus:outline-none focus:border-accent w-full font-sans"
                    required
                  />
                </div>

                <div className="flex flex-col gap-1.5 col-span-2">
                  <label className="font-mono text-[10px] text-slate-400 uppercase tracking-wider">Job Role</label>
                  <input 
                    type="text"
                    placeholder="e.g. Senior Software Engineer"
                    value={role}
                    onChange={(e) => setRole(e.target.value)}
                    className="bg-slate-900 border border-slate-800 rounded px-3 py-2 text-xs text-slate-300 focus:outline-none focus:border-accent w-full font-sans"
                    required
                  />
                </div>

                <div className="flex flex-col gap-1.5">
                  <label className="font-mono text-[10px] text-slate-400 uppercase tracking-wider">Priority Tier</label>
                  <select
                    value={tier}
                    onChange={(e) => setTier(parseInt(e.target.value, 10))}
                    className="bg-slate-900 border border-slate-800 rounded px-3 py-2 text-xs font-mono text-slate-300 focus:outline-none focus:border-accent w-full"
                  >
                    <option value="1">Tier 1 (High)</option>
                    <option value="2">Tier 2 (Medium)</option>
                    <option value="3">Tier 3 (Low)</option>
                  </select>
                </div>

                <div className="flex flex-col gap-1.5">
                  <label className="font-mono text-[10px] text-slate-400 uppercase tracking-wider">Applied Date</label>
                  <input 
                    type="date"
                    value={appliedDate}
                    onChange={(e) => setAppliedDate(e.target.value)}
                    className="bg-slate-900 border border-slate-800 rounded px-3 py-2 text-xs font-mono text-slate-300 focus:outline-none focus:border-accent w-full"
                    required
                  />
                </div>

                <div className="flex flex-col gap-1.5 col-span-2">
                  <label className="font-mono text-[10px] text-slate-400 uppercase tracking-wider">Current Stage</label>
                  <select
                    value={status}
                    onChange={(e) => setStatus(e.target.value as ApplicationStatus)}
                    className="bg-slate-900 border border-slate-800 rounded px-3 py-2 text-xs font-mono text-slate-300 focus:outline-none focus:border-accent w-full"
                  >
                    {STATUSES.map(st => (
                      <option key={st} value={st}>{st}</option>
                    ))}
                  </select>
                </div>

                <div className="flex flex-col gap-1.5 col-span-2">
                  <label className="font-mono text-[10px] text-slate-400 uppercase tracking-wider">Process Notes</label>
                  <textarea 
                    placeholder="Referral detail, interviewer names, next steps..."
                    value={notes}
                    onChange={(e) => setNotes(e.target.value)}
                    rows={3}
                    className="bg-slate-900 border border-slate-800 rounded px-3 py-2 text-xs text-slate-300 focus:outline-none focus:border-accent w-full font-sans"
                  />
                </div>
              </div>

              {/* Action buttons */}
              <div className="flex items-center justify-end gap-3 pt-4 border-t border-slate-800/60 mt-6">
                <button
                  type="button"
                  onClick={() => setIsModalOpen(false)}
                  className="bg-slate-900 hover:bg-slate-800 text-slate-400 font-bold px-4 py-2 rounded text-xs font-mono border border-slate-800 transition-colors"
                >
                  CANCEL
                </button>
                <button
                  type="submit"
                  disabled={createMutation.isPending}
                  className="bg-accent hover:bg-accent-hover text-slate-950 font-bold px-4 py-2 rounded text-xs font-mono transition-colors"
                >
                  LOG_JOB
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {activeNotesPopoverId !== null && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-slate-950/70 p-4 backdrop-blur-sm">
          <div className="w-full max-w-md rounded-2xl border border-slate-800 bg-slate-905 p-5 space-y-4 animate-fade-in shadow-2xl">
            {/* Popover Header */}
            <div className="flex items-center justify-between border-b border-slate-800 pb-2">
              <span className="font-mono text-[10px] font-bold uppercase tracking-wider text-slate-400">
                Process Notes // {applications?.find(a => a.id === activeNotesPopoverId)?.companyName}
              </span>
              <button
                onClick={() => setActiveNotesPopoverId(null)}
                className="text-slate-500 hover:text-slate-350 cursor-pointer"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            </div>

            {/* Popover Body */}
            <textarea
              value={tempNotesText}
              onChange={(e) => setTempNotesText(e.target.value)}
              placeholder="Add referral details, interviewer info, OA questions, or feedback here..."
              rows={6}
              autoFocus
              className="w-full bg-slate-950 border border-slate-800 rounded-lg p-3 text-xs text-slate-200 placeholder-slate-700 outline-none focus:border-accent resize-none font-sans leading-relaxed"
            />

            {/* Popover Footer */}
            <div className="flex items-center justify-end gap-2 pt-2">
              <button
                onClick={() => setActiveNotesPopoverId(null)}
                className="px-3 py-1.5 rounded border border-slate-800 hover:bg-slate-800 text-[10px] font-mono uppercase tracking-wider text-slate-400 transition-colors cursor-pointer"
              >
                Cancel
              </button>
              <button
                onClick={() => {
                  handleNotesChange(activeNotesPopoverId, tempNotesText.trim());
                  setActiveNotesPopoverId(null);
                }}
                className="px-3 py-1.5 rounded bg-accent hover:bg-accent-hover text-slate-950 font-bold text-[10px] font-mono uppercase tracking-wider transition-colors cursor-pointer"
              >
                Save Notes
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export const Dashboard: React.FC = () => {
  // Fetch analytics summary
  const { data: summary, isLoading: isSummaryLoading } = useQuery<AnalyticsSummary>({
    queryKey: ['analyticsSummary'],
    queryFn: async () => {
      const res = await fetch(`${API_URL}/analytics/summary`);
      if (!res.ok) throw new Error('Failed to fetch summary');
      return res.json();
    }
  });

  // Fetch milestones to list top 5 upcoming
  const { data: milestones, isLoading: isMilestonesLoading } = useQuery<Milestone[]>({
    queryKey: ['milestones'],
    queryFn: async () => {
      const res = await fetch(`${API_URL}/milestones`);
      if (!res.ok) throw new Error('Failed to fetch milestones');
      return res.json();
    }
  });

  // Slice milestones to get the next 5 sorted by target date
  const upcomingMilestones = React.useMemo(() => {
    if (!milestones) return [];
    return milestones
      .filter(m => m.status !== 'DONE')
      .slice(0, 5);
  }, [milestones]);

  // Formulate data for the Recharts pie/donut chart
  const categoryChartData = React.useMemo(() => {
    if (!summary || !summary.hoursByCategoryThisWeek) return [];
    return Object.entries(summary.hoursByCategoryThisWeek)
      .map(([category, hours]) => ({
        name: category,
        value: hours
      }))
      .filter(item => item.value > 0); // only show category if worked
  }, [summary]);

  const totalPieHours = React.useMemo(() => {
    return categoryChartData.reduce((sum, item) => sum + item.value, 0);
  }, [categoryChartData]);

  return (
    <div className="flex-1 overflow-y-auto p-8 space-y-8 bg-background">
      {/* Page Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="font-mono text-xl font-bold uppercase tracking-wider text-slate-100">
            Control Center
          </h1>
          <p className="text-xs text-slate-500 font-mono mt-1">
            System status: nominal // live logging metrics active
          </p>
        </div>
        <div className="flex items-center gap-1.5 px-3 py-1.5 bg-slate-900/60 rounded border border-slate-800 font-mono text-[10px] text-emerald-400">
          <span className="w-2 h-2 rounded-full bg-emerald-500 animate-ping" />
          ONLINE_SESSION
        </div>
      </div>

      {/* Summary Widgets Row */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-6">
        {/* Streak card */}
        <div className="bg-panel p-6 rounded-lg border border-slate-800 flex items-center justify-between group transition-all duration-300 hover:border-orange-500/20">
          <div className="space-y-1">
            <span className="text-[10px] font-mono text-slate-500 uppercase tracking-widest block">
              Current Streak
            </span>
            <div className="font-mono text-2xl font-bold text-slate-100 flex items-baseline gap-1">
              {isSummaryLoading ? '...' : summary?.currentStreakDays}
              <span className="text-xs text-slate-500 font-normal">days</span>
            </div>
            <span className="text-[10px] font-mono text-orange-500/80 block">
              max: {summary?.longestStreakDays || 0} days
            </span>
          </div>
          <div className="w-12 h-12 rounded-lg bg-orange-500/10 flex items-center justify-center border border-orange-500/30 text-orange-500 group-hover:scale-105 transition-transform duration-200">
            <Flame className="w-6 h-6" />
          </div>
        </div>

        {/* Total Hours Card */}
        <div className="bg-panel p-6 rounded-lg border border-slate-800 flex items-center justify-between group transition-all duration-300 hover:border-blue-500/20">
          <div className="space-y-1">
            <span className="text-[10px] font-mono text-slate-500 uppercase tracking-widest block">
              Total Hours
            </span>
            <div className="font-mono text-2xl font-bold text-slate-100 flex items-baseline gap-1">
              {isSummaryLoading ? '...' : summary?.totalHoursAllTime}
              <span className="text-xs text-slate-500 font-normal">hrs</span>
            </div>
            <span className="text-[10px] font-mono text-slate-500 block">
              cumulative logs
            </span>
          </div>
          <div className="w-12 h-12 rounded-lg bg-blue-500/10 flex items-center justify-center border border-blue-500/30 text-blue-500 group-hover:scale-105 transition-transform duration-200">
            <Clock className="w-6 h-6" />
          </div>
        </div>

        {/* Hours This Week Card */}
        <div className="bg-panel p-6 rounded-lg border border-slate-800 flex items-center justify-between group transition-all duration-300 hover:border-cyan-500/20">
          <div className="space-y-1">
            <span className="text-[10px] font-mono text-slate-500 uppercase tracking-widest block">
              This Week
            </span>
            <div className="font-mono text-2xl font-bold text-slate-100 flex items-baseline gap-1">
