              Hours This Week by Category
            </h2>
            <ArrowUpRight className="w-4 h-4 text-slate-500" />
          </div>

          <div className="flex-1 relative flex items-center justify-center">
            {isSummaryLoading ? (
              <div className="text-xs font-mono text-slate-500 animate-pulse">
                compiling_chart...
