export const requireAuth = async (req: Request, res: Response, next: NextFunction) => {
  // 1. Check for local dev bypass FIRST
  if (!supabase) {
    (req as any).userId = null;
    (req as any).user = null;
    return next();
  }

  // 2. Only enforce authorization if JWT is configured
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Authorization token required' });
  }

  const token = authHeader.split(' ')[1];

  try {
    // Verify using Supabase SDK directly (supports both HS256 and ES256 automatically!)
    const { data: { user }, error } = await supabase.auth.getUser(token);

    if (error || !user) {
      console.error('[Auth Middleware] Verification failed:', error?.message || 'No user found');
      return res.status(401).json({ error: 'Invalid or expired token' });
    }

    const supabaseUserId = user.id;
    const email = user.email;
    const name = user.user_metadata?.full_name || null;

    if (!supabaseUserId) {
      return res.status(401).json({ error: 'Invalid token payload: user ID not found.' });
    }

    // Sync user with our database
    let localUser = await prisma.user.findUnique({
      where: { id: supabaseUserId }
    });

    if (!localUser) {
      localUser = await prisma.user.create({
        data: {
          id: supabaseUserId,
          email: email || '',
          name: name
        }
      });
    }

    // Attach user information to the request
    (req as any).userId = supabaseUserId;
    (req as any).user = localUser;

    next();
  } catch (error: any) {
    console.error('[Auth Middleware] Exception:', error.message);
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
};

function calculateStreaks(dates: string[]): { currentStreakDays: number; longestStreakDays: number } {
  if (dates.length === 0) return { currentStreakDays: 0, longestStreakDays: 0 };

  const todayStr = new Date().toISOString().split('T')[0];
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  const yesterdayStr = yesterday.toISOString().split('T')[0];

  const hasToday = dates.includes(todayStr);
  const hasYesterday = dates.includes(yesterdayStr);

  let currentStreakDays = 0;
  if (hasToday || hasYesterday) {
    let currentRef = hasToday ? new Date(todayStr) : new Date(yesterdayStr);
    currentStreakDays = 1;

    while (true) {
      const nextDay = new Date(currentRef);
      nextDay.setDate(nextDay.getDate() - 1);
      const nextDayStr = nextDay.toISOString().split('T')[0];
      if (dates.includes(nextDayStr)) {
        currentStreakDays++;
        currentRef = nextDay;
      } else {
        break;
      }
    }
  }

  const sortedDates = [...new Set(dates)].sort().map(d => new Date(d));
  let longestStreakDays = 1;
  let runningStreak = 1;

  for (let i = 1; i < sortedDates.length; i++) {
    const diffTime = sortedDates[i].getTime() - sortedDates[i-1].getTime();
    const diffDays = Math.round(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays === 1) {
      runningStreak++;
      if (runningStreak > longestStreakDays) {
        longestStreakDays = runningStreak;
      }
    } else if (diffDays > 1) {
      runningStreak = 1;
    }
  }

  return { 
    currentStreakDays, 
    longestStreakDays: Math.max(longestStreakDays, currentStreakDays) 
  };
}

async function updateMilestoneProgress(milestoneId: number) {
  const milestone = await prisma.milestone.findUnique({
    where: { id: milestoneId },
    include: { tasks: true }
  });

  if (!milestone) return;

  const totalTasks = milestone.tasks.length;
  if (totalTasks === 0) {
    return;
  }

  const completedTasks = milestone.tasks.filter(t => t.isDone).length;
  const progressPct = Math.round((completedTasks / totalTasks) * 100);

  let status = milestone.status;
  if (progressPct === 100) {
    status = MilestoneStatus.DONE;
  } else if (progressPct > 0) {
    status = MilestoneStatus.IN_PROGRESS;
  } else {
    status = MilestoneStatus.NOT_STARTED;
  }

  await prisma.milestone.update({
    where: { id: milestoneId },
    data: { progressPct, status }
  });
}

